messages.author.template.view:
import { useCasePhases } from '@microteia/data';

export default function View() {
  const phases = useCasePhases();
  return (
    <div style={{ padding: 16 }}>
      Minha extensão — {phases.length} fase(s) cadastrada(s).
    </div>
  );
}

